package api

import (
	"reflect"
	"sort"
	"strings"
)

// Field is one parameter, as reported by the schema action.
type Field struct {
	Name     string   `json:"name"`
	Type     string   `json:"type"`
	Required bool     `json:"required,omitempty"`
	Enum     []string `json:"enum,omitempty"`
	Default  string   `json:"default,omitempty"`
	Desc     string   `json:"desc,omitempty"`
}

// Schema is the machine-readable description returned by the schema action.
// It is generated by reflecting over the same structs the decoder uses, so it
// cannot describe a parameter the decoder would reject or miss one it accepts.
type Schema struct {
	Version int                 `json:"version"`
	Defs    map[string]TypeSpec `json:"defs"`
	Actions []ActionSpec        `json:"actions"`
	Guide   map[string]any      `json:"guide"`
}

// TypeSpec describes a named, reusable parameter object.
type TypeSpec struct {
	Properties map[string]fieldSpec `json:"properties"`
	Required   []string             `json:"required,omitempty"`
	Note       string               `json:"note,omitempty"`
}

// ActionSpec describes one action and its parameter object.
type ActionSpec struct {
	Name    string         `json:"name"`
	Summary string         `json:"summary"`
	Params  map[string]any `json:"params"`
}

// builder accumulates defs while walking the registered parameter structs.
type builder struct {
	defs map[string]TypeSpec
}

func newBuilder() *builder { return &builder{defs: map[string]TypeSpec{}} }

// field describes one parameter inside a params object. Ref, when set, names a
// def that carries the object's fields.
type fieldSpec struct {
	Field
	Ref string `json:"ref,omitempty"`
}

// paramsSpec returns the schema for an action's parameter struct.
func (b *builder) paramsSpec(t reflect.Type) map[string]any {
	props, required := b.walk(t)
	out := map[string]any{"properties": props}
	if len(required) > 0 {
		out["required"] = required
	}
	return out
}

// walk flattens embedded structs (encoding/json promotes their fields the same
// way) and turns nested struct types into named defs.
func (b *builder) walk(t reflect.Type) (map[string]fieldSpec, []string) {
	props := map[string]fieldSpec{}
	var required []string
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if f.PkgPath != "" { // unexported
			continue
		}
		if f.Anonymous && deref(f.Type).Kind() == reflect.Struct {
			inner, innerReq := b.walk(deref(f.Type))
			for k, v := range inner {
				props[k] = v
			}
			required = append(required, innerReq...)
			continue
		}
		name := jsonNameOf(f)
		if name == "-" {
			continue
		}
		props[name] = b.fieldSpecFor(f, name)
		if f.Tag.Get("req") == "1" {
			required = append(required, name)
		}
	}
	sort.Strings(required)
	return props, required
}

func (b *builder) fieldSpecFor(f reflect.StructField, name string) fieldSpec {
	spec := fieldSpec{Field: Field{
		Name:     name,
		Required: f.Tag.Get("req") == "1",
		Enum:     splitList(f.Tag.Get("enum")),
		Default:  f.Tag.Get("def"),
		Desc:     f.Tag.Get("desc"),
	}}

	t := deref(f.Type)
	switch {
	case t.Kind() == reflect.Struct:
		spec.Type = "object"
		spec.Ref = b.define(t)
	case t.Kind() == reflect.Slice && deref(t.Elem()).Kind() == reflect.Struct:
		spec.Type = "object[]"
		spec.Ref = b.define(deref(t.Elem()))
	default:
		spec.Type = goTypeOf(t)
	}
	return spec
}

// define registers a def once and returns its name. Recursion is stopped by
// inserting the entry before walking the fields.
func (b *builder) define(t reflect.Type) string {
	name := t.Name()
	if name == "" {
		return ""
	}
	if _, seen := b.defs[name]; seen {
		return name
	}
	b.defs[name] = TypeSpec{}
	props, required := b.walk(t)
	b.defs[name] = TypeSpec{
		Properties: props,
		Required:   required,
		Note:       typeNotes[name],
	}
	return name
}

func (b *builder) schema() Schema {
	actions := make([]ActionSpec, 0, len(actionNames))
	for _, name := range actionNames {
		a := registry[name]
		actions = append(actions, ActionSpec{
			Name:    a.name,
			Summary: a.summary,
			Params:  b.paramsSpec(a.paramsType),
		})
	}
	return Schema{
		Version: 3,
		Defs:    b.defs,
		Actions: actions,
		Guide: map[string]any{
			"constraints": []string{
				"no action sends mail: draft writes the message into Mail.app's Drafts mailbox for the user to review and send",
				"no action deletes mail: messages.quarantine moves messages into a holding mailbox, which is reversible from Mail.app",
				`every mutation accepts "dryRun": true, which reports what it would touch and changes nothing`,
				"mutations take all ids in one call; with no \"in\" the ids are resolved globally, because Mail.app message ids are unique database-wide",
				`reads accept "format": "compact" to drop fields that are empty for the query`,
			},
			"input": []string{
				"pass the request document as the first argument or on stdin",
				`a document is either one operation {"action":...,"params":{...}} or a batch {"ops":[...]}`,
				`"params" carries that action's parameters and nothing else; unknown parameters are rejected, not ignored`,
				`document level settings sit next to "action": "pretty": true indents the output`,
				"exit code is 0 when every operation succeeded, 1 otherwise; the envelope is always printed",
			},
		},
	}
}

func deref(t reflect.Type) reflect.Type {
	for t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	return t
}

func goTypeOf(t reflect.Type) string {
	switch t.Kind() {
	case reflect.String:
		return "string"
	case reflect.Bool:
		return "bool"
	case reflect.Int, reflect.Int64:
		return "int"
	case reflect.Slice:
		return goTypeOf(t.Elem()) + "[]"
	case reflect.Map, reflect.Struct:
		return "object"
	default:
		return t.Kind().String()
	}
}

func jsonNameOf(f reflect.StructField) string {
	name := strings.Split(f.Tag.Get("json"), ",")[0]
	if name == "" {
		name = f.Name
	}
	return name
}

func splitList(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, "|")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

func contains(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}
